/*	Fail the run if Administrate returned any error.	*/
/*	HTTP 200 does not mean success - inspect the top-level AND nested errors arrays.	*/
const items_ary = $input.all();

for (const item_obj of items_ary)
{
	const response_obj = item_obj.json || {};
	const topErrors_ary = Array.isArray(response_obj.errors) ? response_obj.errors : [];
	const nested_ary = [];
	const data_obj = response_obj.data || null;

	if (data_obj)
	{
		for (const domain_str of Object.keys(data_obj))
		{
			const domain_obj = data_obj[domain_str];
			if (domain_obj && typeof domain_obj === 'object')
			{
				for (const field_str of Object.keys(domain_obj))
				{
					const field_var = domain_obj[field_str];
					if (field_var && Array.isArray(field_var.errors) && field_var.errors.length > 0)
					{
						nested_ary.push(...field_var.errors);
					}
				}
			}
		}
	}

	if (topErrors_ary.length > 0 || nested_ary.length > 0)
	{
		const all_ary = topErrors_ary.concat(nested_ary);
		throw new Error('Administrate returned errors: ' + JSON.stringify(all_ary));
	}
}

return items_ary;

/*	Collapse the filtered learners result to zero or one learner id.	*/
const contactId_str = $('Set Contact Context').item.json.contactId;
const eventId_str = $('Set Contact Context').item.json.eventId;
const email_str = $('Set Contact Context').item.json.email;

const response_obj = $input.first().json || {};
let learnerId_var = null;
try
{
	learnerId_var = response_obj.data.learners.edges[0].node.id || null;
} catch (error) {
	learnerId_var = null;
}

const alreadyRegistered_bln = (learnerId_var !== null);

return [{ json: {
	alreadyRegistered: alreadyRegistered_bln,
	learnerId: learnerId_var,
	contactId: contactId_str,
	eventId: eventId_str,
	email: email_str
} }];

/*	Read the new learner id straight off the registerNamedLearners payload. Check Errors (Register) has	*/
/*	already proved it is there.	*/
const context_obj = $('Set Contact Context').first().json;
const response_obj = $input.first().json || {};

let learnerId_var = null;
try
{
	learnerId_var = response_obj.data.event.registerNamedLearners[0].learners[0].id || null;
} catch (error) {
	learnerId_var = null;
}

if (learnerId_var === null)
{
	throw new Error('Could not read the new learner id from the registerNamedLearners response for contact ' + context_obj.contactId);
}

return [{ json: {
	alreadyRegistered: false,
	learnerId: learnerId_var,
	contactId: context_obj.contactId,
	eventId: context_obj.eventId,
	email: context_obj.email
} }];

/*	Fail fast only when Config itself is broken.	*/
/*	A missing or unknown eventId is an attendee problem, not a configuration one, so it is deliberately	*/
/*	NOT thrown here. Fetch Event returns nothing, Resolve Session sets outcome 'invalid-event', and the	*/
/*	attendee reaches the 'Check-in unavailable' screen through Build Log Row instead of a raw n8n error page.	*/
const config_obj = $('Config').item.json;
const missing_ary = [];

if (String(config_obj.GRAPHQL_URL || '').trim() === '')
{
	missing_ary.push('GRAPHQL_URL');
}

if (missing_ary.length > 0)
{
	throw new Error('Cannot check in - missing Config: ' + missing_ary.join(', '));
}

return $input.all();

/*	Only EMAIL_USAGE is required to create a walk-in contact. The account is derived from the	*/
/*	Domain Lookup / Company Lookup cascade, so there is no ACCOUNT_ID in Config to fall back to.	*/
const config_obj = $('Config').item.json;
const required_ary = ['EMAIL_USAGE'];
const missing_ary = [];

for (const key_str of required_ary)
{
	if (String(config_obj[key_str] || '').trim() === '')
	{
		missing_ary.push(key_str);
	}
}

if (missing_ary.length > 0)
{
	throw new Error('Cannot create a new walk-in contact - set these in Config: ' + missing_ary.join(', '));
}

return $input.all();

/*	Decide the account for the new contact: single domain match, then single company match, else an individual account.	*/
const email_str = String($('Class Check-In (QR)').item.json['Email address'] || '');
const company_str = String($('Ask Name').item.json['Company (optional)'] || '').trim();

const domainAccounts_obj = {};
try
{
	for (const edge_obj of $('Domain Lookup').item.json.data.contacts.edges)
	{
		const acc_obj = edge_obj.node && edge_obj.node.account;
		if (acc_obj && acc_obj.id)
		{
			domainAccounts_obj[acc_obj.id] = acc_obj.name || '';
		}
	}
} catch (e_var) {}
const domainIds_ary = Object.keys(domainAccounts_obj);

const companyAccounts_obj = {};
if (company_str !== '')
{
	try
	{
		for (const edge_obj of $('Company Lookup').item.json.data.accounts.edges)
		{
			const node_obj = edge_obj.node;
			if (node_obj && node_obj.id)
			{
				companyAccounts_obj[node_obj.id] = node_obj.name || '';
			}
		}
	} catch (e_var) {}
}
const companyIds_ary = Object.keys(companyAccounts_obj);

let accountId_str = '';
let status_str = '';
let method_str = '';
let suggestedName_str = '';

if (domainIds_ary.length === 1)
{
	accountId_str = domainIds_ary[0];
	suggestedName_str = domainAccounts_obj[accountId_str];
	status_str = 'reconciled-domain';
	method_str = 'domain';
} else if (company_str !== '' && companyIds_ary.length === 1) {
	accountId_str = companyIds_ary[0];
	suggestedName_str = companyAccounts_obj[accountId_str];
	status_str = 'reconciled-company';
	method_str = 'company';
} else if (domainIds_ary.length > 1) {
	status_str = 'needs-review-multiple-domain';
	method_str = 'domain-ambiguous';
} else if (company_str !== '' && companyIds_ary.length > 1) {
	status_str = 'needs-review-multiple-company';
	method_str = 'company-ambiguous';
} else {
	status_str = 'needs-review-none';
	method_str = 'none';
}

/*	Reconciled to a single real account -> file there; otherwise create an individual account.	*/
const mode_str = accountId_str !== '' ? 'account' : 'individual';

return [{ json: {
	mode: mode_str,
	accountId: accountId_str,
	status: status_str,
	matchMethod: method_str,
	suggestedAccountName: suggestedName_str,
	company: company_str,
	email: email_str
} }];

/*	=== One log row per scan, whatever happened ===	*/
