} else if (result_str === 'not-open-yet') {
	title_str = 'Check-in isn\'t open yet';
	message_str = 'Check-in' + (eventTitle_str !== '' ? ' for ' + eventTitle_str : '') + ' opens at ' + String(session_obj.opensAtLabel || 'a later time') + ', ' + openLead_str + ' before the class starts. Please scan again then, or see reception.';
	logStatus_str = 'warning';
} else if (result_str === 'closed') {
	title_str = 'Check-in has closed';
	message_str = 'Check-in for this class is no longer open. Please see a member of staff.';
	logStatus_str = 'warning';
} else if (result_str === 'reception-unknown-email' || result_str === 'reception-not-booked') {
	title_str = 'Please see reception';
	message_str = 'We could not find a booking for you on this class. Please see reception, who will check you in.';
	logStatus_str = 'warning';
} else if (result_str === 'registration-refused') {
	title_str = 'Could not add you to this class';
	message_str = 'You reached the right page, but we were not able to register you for this class automatically. Nothing has gone wrong at your end. Please see a member of staff, who will complete your check-in.';
} else if (result_str === 'walk-in-failed') {
	title_str = 'We could not set up your details';
	message_str = 'Nothing has gone wrong at your end. Please see a member of staff, who will complete your check-in.';
} else if (result_str === 'attendance-refused') {
	title_str = 'Check-in not completed';
	message_str = 'You are registered for this class, so nothing is lost, but we could not mark your attendance automatically. Please see a member of staff, who will complete your check-in.';
} else if (result_str === 'invalid-event' || result_str === 'no-sessions') {
	title_str = 'Check-in unavailable';
	message_str = 'We could not check you in automatically. Please see a member of staff, who will get you checked in.';
}

return [{ json: {
	timestamp: new Date().toISOString(),
	eventId: String(session_obj.eventId || context_obj.eventId || ''),
	eventTitle: eventTitle_str,
	email: email_str,
	domain: domain_str,
