	hasPassed: false,
	result: result_str,
	sessionTitle: String(session_obj.sessionTitle || ''),
	sessionStart: String(session_obj.sessionStart || ''),
	staleScan: !!session_obj.staleScan,
	windowOverridden: !!session_obj.windowOverridden,
	logStatus: logStatus_str,
	screenTitle: title_str,
	screenMessage: message_str
} }];

