/*	registerNamedLearners returns a LIST of responses, one per learner, so its errors sit inside an array.	*/
/*	Walk the whole response rather than assuming a shape: a refusal missed here would read as success.	*/
function collectErrors(value_var, found_ary)
{
	if (Array.isArray(value_var))
	{
		for (const entry_var of value_var)
		{
			collectErrors(entry_var, found_ary);
		}
		return;
	}
	if (value_var && typeof value_var === 'object')
	{
		for (const key_str of Object.keys(value_var))
		{
			if (key_str === 'errors' && Array.isArray(value_var[key_str]))
			{
				found_ary.push(...value_var[key_str]);
			} else {
				collectErrors(value_var[key_str], found_ary);
			}
		}
	}
}

const items_ary = $input.all();

for (const item_obj of items_ary)
{
	const found_ary = [];
	collectErrors(item_obj.json || {}, found_ary);

	if (found_ary.length > 0)
	{
		/*	Keep the message SHORT. A long JSON dump is truncated from the front on the error output.	*/
		const summary_str = found_ary.map(function (error_obj)
		{
			return (String(error_obj.label || 'error') + ': ' + String(error_obj.message || ''));
		}).join('; ');
		throw new Error('Administrate refused registration - ' + summary_str);
	}

	let learnerId_var = null;
	try
	{
		learnerId_var = item_obj.json.data.event.registerNamedLearners[0].learners[0].id || null;
	} catch (error) {
		learnerId_var = null;
	}

	if (learnerId_var === null)
	{
		throw new Error('Administrate returned no errors but no learner either, so registration is treated as refused.');
	}
}

return items_ary;

