					}
				}
			}
		}
	}

	if (topErrors_ary.length > 0 || nested_ary.length > 0)
	{
		const all_ary = topErrors_ary.concat(nested_ary);
		/*	Short message for the same reason as Check Errors (Register). 'Learners missing from session'	*/
		/*	is the one that matters here: event registration does not imply session membership.	*/
		const summary_str = all_ary.map(function (error_obj)
		{
			return (String(error_obj.label || 'error') + ': ' + String(error_obj.message || ''));
		}).join('; ');
		throw new Error('Administrate refused the attendance mark - ' + summary_str);
	}
}

return items_ary;

/*	=== Decide which session this scan is for, and whether check-in is open for it ===	*/
/*	Check-in opens OPEN_MINUTES_BEFORE before a session starts and closes CLOSE_HOURS_AFTER after it	*/
/*	starts. Both are measured from timeZonedStart, which carries its own UTC offset, so the answer is	*/
/*	the same whatever clock the n8n server runs on. This runs BEFORE anything is written to Administrate,	*/
/*	so a scan outside the window registers nobody and marks nothing.	*/
const config_obj = $('Config').first().json;
const form_obj = $('Class Check-In (QR)').first().json;
const response_obj = $input.first().json || {};

const email_str = String(form_obj['Email address'] || '').trim();
const eventIdIn_str = String(form_obj.eventId || '').trim();
const scannedSessionId_str = String(form_obj.sessionId || '').trim();

const openParsed_int = parseInt(String(config_obj.OPEN_MINUTES_BEFORE || '120').trim(), 10);
const openMinutes_int = isNaN(openParsed_int) ? 120 : openParsed_int;
const closeParsed_num = parseFloat(String(config_obj.CLOSE_HOURS_AFTER || '12').trim());
const closeHours_num = isNaN(closeParsed_num) ? 12 : closeParsed_num;
const override_str = String(config_obj.CHECKIN_WINDOW_OVERRIDE || 'off').trim().toLowerCase();
const selfTypes_ary = String(config_obj.SELF_REGISTER_EVENT_TYPES || '').split(',').map(function (type_str) { return type_str.trim().toLowerCase(); }).filter(function (type_str) { return type_str !== ''; });

let event_obj = null;
try
{
	event_obj = response_obj.data.events.edges[0].node || null;
} catch (error) {
	event_obj = null;
}

function formatWhen(ms_int, timeZone_str)
{
	const zone_str = timeZone_str || 'Europe/London';
	try
	{
		const date_var = new Date(ms_int);
		const time_str = date_var.toLocaleTimeString('en-GB', { timeZone: zone_str, hour: '2-digit', minute: '2-digit' });
		const day_str = date_var.toLocaleDateString('en-GB', { timeZone: zone_str, weekday: 'long', day: 'numeric', month: 'long' });
		return time_str + ' on ' + day_str;
	} catch (error) {
		return new Date(ms_int).toISOString();
	}
}

const out_obj = {
	email: email_str,
	eventId: eventIdIn_str,
	eventTitle: event_obj ? String(event_obj.title || '') : '',
	eventType: event_obj ? String(event_obj.type || '') : '',
	scannedSessionId: scannedSessionId_str,
	sessionId: '',
	sessionTitle: '',
	sessionStart: '',
	sessionTimeZone: '',
	staleScan: false,
	windowOverridden: false,
	opensAtLabel: '',
	openMinutes: openMinutes_int,
	closeHours: closeHours_num,
	selfRegister: false,
	proceed: false,
	outcome: ''
};

if (eventIdIn_str === '' || event_obj === null)
{
	out_obj.outcome = 'invalid-event';
	return [{ json: out_obj }];
}

out_obj.selfRegister = (selfTypes_ary.indexOf(String(event_obj.type || '').toLowerCase()) !== -1);

let sessions_ary = [];
try
{
	sessions_ary = event_obj.sessions.edges.map(function (edge_obj) { return edge_obj.node; });
} catch (error) {
	sessions_ary = [];
}

const now_int = Date.now();
const candidates_ary = [];

/*	A session that spans several days (for example one session from Monday to Wednesday)	*/
/*	gets a window on EACH day it covers, starting at the session's own start time on that day. Without	*/
/*	this, nobody could check in on day two, because day two is more than 12 hours after the start.	*/
for (const session_obj of sessions_ary)
{
	const start_int = Date.parse(String(session_obj.timeZonedStart || ''));
	if (isNaN(start_int))
	{
		continue;
	}
	const endParsed_int = Date.parse(String(session_obj.timeZonedEnd || ''));
	const end_int = isNaN(endParsed_int) ? start_int : endParsed_int;
	for (let day_int = 0; day_int < 60; day_int++)
	{
		const occurrence_int = start_int + (day_int * 86400000);
		if (day_int > 0 && occurrence_int > end_int)
		{
			break;
		}
		const open_int = occurrence_int - (openMinutes_int * 60000);
		const close_int = occurrence_int + Math.round(closeHours_num * 3600000);
		candidates_ary.push({
			session: session_obj,
			start: occurrence_int,
			open: open_int,
			inWindow: (now_int >= open_int && now_int <= close_int),
			distance: Math.abs(now_int - occurrence_int)
		});
	}
}

if (candidates_ary.length === 0)
{
	out_obj.outcome = 'no-sessions';
	return [{ json: out_obj }];
}

/*	A scanned session code is honoured only while its own window is open. Otherwise the open session	*/
/*	nearest its start wins, so a day-one code scanned on day two marks day two, not day one.	*/
let chosen_var = null;
for (const candidate_obj of candidates_ary)
{
	if (scannedSessionId_str !== '' && String(candidate_obj.session.id) === scannedSessionId_str && candidate_obj.inWindow)
	{
		chosen_var = candidate_obj;
	}
}

if (chosen_var === null)
{
	for (const candidate_obj of candidates_ary)
	{
		if (candidate_obj.inWindow && (chosen_var === null || candidate_obj.distance < chosen_var.distance))
		{
			chosen_var = candidate_obj;
		}
	}
}

/*	TEST OVERRIDE ONLY. 'any' ignores the window entirely: the scanned session if there is one,	*/
/*	otherwise the session nearest now. Must be 'off' in production.	*/
if (chosen_var === null && override_str === 'any')
{
	for (const candidate_obj of candidates_ary)
	{
		if (scannedSessionId_str !== '' && String(candidate_obj.session.id) === scannedSessionId_str)
		{
			chosen_var = candidate_obj;
		}
	}
	if (chosen_var === null)
	{
		for (const candidate_obj of candidates_ary)
		{
			if (chosen_var === null || candidate_obj.distance < chosen_var.distance)
			{
				chosen_var = candidate_obj;
			}
		}
	}
	out_obj.windowOverridden = true;
}

if (chosen_var === null)
{
	let nextOpen_var = null;
	for (const candidate_obj of candidates_ary)
	{
		if (candidate_obj.open > now_int && (nextOpen_var === null || candidate_obj.open < nextOpen_var.open))
		{
			nextOpen_var = candidate_obj;
		}
	}
	if (nextOpen_var !== null)
	{
		out_obj.outcome = 'not-open-yet';
		out_obj.opensAtLabel = formatWhen(nextOpen_var.open, nextOpen_var.session.timeZoneName);
		out_obj.sessionId = String(nextOpen_var.session.id || '');
		out_obj.sessionTitle = String(nextOpen_var.session.title || '');
		out_obj.sessionStart = String(nextOpen_var.session.timeZonedStart || '');
	} else {
		out_obj.outcome = 'closed';
	}
	return [{ json: out_obj }];
}

out_obj.sessionId = String(chosen_var.session.id || '');
out_obj.sessionTitle = String(chosen_var.session.title || '');
out_obj.sessionStart = String(chosen_var.session.timeZonedStart || '');
out_obj.sessionTimeZone = String(chosen_var.session.timeZoneName || '');
out_obj.staleScan = (scannedSessionId_str !== '' && scannedSessionId_str !== out_obj.sessionId);
out_obj.proceed = true;

return [{ json: out_obj }];

/*	The session was settled by Resolve Session before anything was written. The learner id comes from	*/
/*	whichever registration branch ran: a new registration, or the existing one Check Registration found.	*/
let learnerId_str = '';
if ($('Extract Learner Id').isExecuted)
{
	learnerId_str = String($('Extract Learner Id').first().json.learnerId || '');
}
if (learnerId_str === '' && $('Evaluate Registration').isExecuted)
{
	learnerId_str = String($('Evaluate Registration').first().json.learnerId || '');
}

const session_obj = $('Resolve Session').first().json;

return [{ json: {
	learnerId: learnerId_str,
	sessionId: String(session_obj.sessionId || ''),
	eventId: String(session_obj.eventId || '')
} }];
